  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Yakir Aharonov",
        "Michael V. Berry"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect established that quantum phase can reveal physical consequences of electromagnetic potentials, while Berry phase generalized geometric phase across quantum physics. Together these are deep, durable insights with broad influence.",
        "attribution": "Aharonov is central to the effect bearing his name; Berry's generalization made geometric phase a widely useful principle. The two contributions are distinct and fit the prize limit.",
        "maturity": "Both ideas have been confirmed and developed extensively across several decades.",
        "uncertainties": [
          "The ballot groups two related but historically distinct contributions, so the prize citation would need to define their shared discovery carefully."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Masaomi Tanaka"
      ],
      "assessment": {
        "nobel_worthiness": "The observation of a neutron-star merger producing a kilonova connected gravitational-wave astronomy with the origin of heavy elements, a major empirical advance in astrophysics.",
        "attribution": "Metzger and Kasen helped establish the radioactive r-process-powered kilonova interpretation; Tanaka made important contributions to modeling the spectra and light curves. The observational discovery involved a much larger collaboration.",
        "maturity": "The multi-messenger event and its kilonova are firmly observed, and the merger origin of heavy-element production has strong support.",
        "uncertainties": [
          "The relative contributions of theory, modeling, and the large observing teams require careful assessment.",
          "The event strongly supports an r-process contribution but does not settle the full astrophysical inventory of heavy elements."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B061",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision map of cosmic microwave background anisotropies transformed cosmology into a quantitatively constrained field and enabled precise estimates of fundamental cosmic parameters.",
        "attribution": "Bennett and Page represent the instrument and mission leadership; Spergel made central contributions to extracting cosmological implications. Credit must recognize the wider team while identifying the individual advances.",
        "maturity": "The measurements have been tested and refined by later observations, and their cosmological impact is established.",
        "uncertainties": [
          "The boundary between WMAP's distinctive contribution and the broader sequence of CMB experiments needs careful delineation."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Sheperd S. Doeleman",
        "Heino Falcke",
        "J. Anton Zensus"
      ],
      "assessment": {
        "nobel_worthiness": "Imaging the shadow-scale structure around a black hole made a striking test of strong-field gravity and demonstrated a remarkable new use of global very-long-baseline interferometry.",
        "attribution": "Falcke's early proposal, Doeleman's leadership of the observational effort, and Zensus's contributions to the VLBI program represent complementary parts of the achievement. The collaboration's scale makes individual attribution difficult.",
        "maturity": "The images and subsequent observations provide substantial confirmation, though the result depends on sophisticated reconstruction from sparse interferometric data.",
        "uncertainties": [
          "The credit assigned to the three named individuals relative to other essential members of the collaboration needs independent scrutiny."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Frans Pretorius",
        "John G. Baker",
        "Manuela Campanelli"
      ],
      "assessment": {
        "nobel_worthiness": "Stable numerical simulations of binary black-hole mergers made it possible to model the final inspiral and merger, a crucial bridge between general relativity and gravitational-wave observations.",
        "attribution": "Pretorius's breakthrough and the independent breakthroughs by the Baker and Campanelli groups collectively established the needed simulations. The parallel nature of the work complicates a single concise account of credit.",
        "maturity": "The methods are extensively validated by detections and are now standard tools in gravitational-wave astronomy.",
        "uncertainties": [
          "The division of priority and the relative indispensability of each advance should be established from the technical history."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur K. Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "BB84 and E91 joined quantum principles to secure communication and helped create quantum information science as a field with clear physical foundations and real applications.",
        "attribution": "Bennett and Brassard introduced BB84; Ekert independently developed an entanglement-based protocol that connected security to Bell correlations. The contributions are complementary and identifiable.",
        "maturity": "The protocols have been tested in many implementations and their principles are well established.",
        "uncertainties": [
          "The scale of practical deployment and the enduring physical significance of communication protocols relative to other quantum-information advances remain matters of judgment."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B042",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Gerard 't Hooft"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is an exceptionally influential conceptual connection between quantum field theory and gravity, with deep consequences for theoretical physics.",
        "attribution": "Maldacena's duality proposal is the defining advance; 't Hooft's and Witten's earlier and subsequent contributions helped establish the holographic framework and its significance.",
        "maturity": "The correspondence has been developed and tested mathematically in many settings, but it remains without direct empirical confirmation as a description of nature.",
        "uncertainties": [
          "The physical status of the duality outside controlled theoretical examples is unresolved.",
          "Credit spans foundational ideas and later formulations whose boundaries are not simple."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Alan H. Guth",
        "Alexei A. Starobinsky",
        "Andrei Linde"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers a powerful framework for explaining large-scale features of the universe and the origin of primordial structure, with major influence on cosmology.",
        "attribution": "Guth and Starobinsky developed early inflationary models independently, and Linde made influential advances that shaped the framework. Mukhanov's contribution to quantum perturbations is also important to the discovery as framed.",
        "maturity": "The framework is consistent with many observations, but inflation itself and the mechanism that generated it have not been uniquely established.",
        "uncertainties": [
          "There is no decisive observation that selects inflation over all alternatives or identifies a specific inflationary model.",
          "The attribution depends on whether the prize recognizes the initial mechanism, its viable development, or the origin of observed structure."
        ]
      }
    }
  ]
}
